fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }
    // Compute the effective rotation modulo n
    let off = offset % n;

    // Build the rotated array by concatenating two slices
    let mut b = Vec::with_capacity(n);
    b.extend_from_slice(&a[off..]);
    b.extend_from_slice(&a[..off]);
    b
}

